/* @autogenerated */
package net.civeira.phylax.feature.oauth.client.infrastructure.driven;

import java.net.InetAddress;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * Remote JWKS URLs that cannot be used to reach internal services (task 3.3).
 */
class RemoteJwksFetcherUnitTest {

  @Test
  @DisplayName("Only HTTPS URLs without user info are fetched")
  void only_https() {
    Assertions.assertTrue(RemoteJwksFetcher.allowed("http://8.8.8.8/jwks").isEmpty());
    Assertions.assertTrue(RemoteJwksFetcher.allowed("file:///etc/passwd").isEmpty());
    Assertions.assertTrue(RemoteJwksFetcher.allowed("https://user:pw@8.8.8.8/jwks").isEmpty());
    Assertions.assertTrue(RemoteJwksFetcher.allowed("https://8.8.8.8/jwks").isPresent());
  }

  @Test
  @DisplayName("Loopback, private, link-local and unique-local hosts are refused")
  void internal_hosts_refused() throws Exception {
    for (String host : new String[] {"https://localhost/jwks", "https://127.0.0.1/jwks",
        "https://10.1.2.3/jwks", "https://192.168.1.1/jwks", "https://172.16.0.1/jwks",
        "https://169.254.169.254/latest", "https://[::1]/jwks", "https://[fd00::1]/jwks",
        "https://100.64.0.1/jwks", "https://0.0.0.0/jwks"}) {
      Assertions.assertTrue(RemoteJwksFetcher.allowed(host).isEmpty(), host);
    }
    Assertions.assertFalse(RemoteJwksFetcher.internal(InetAddress.getByName("8.8.8.8")));
  }
}
